// Chat op elke gidspagina van curacao.day (Henkjan 9 nov 2026: "Zorg dat op alle paginas links staan naar de chat op relevante plekken en op alle
// paginas de chat box"): onder de kop een regel die het chatvenster van curacao.day opent met het onderwerp van de pagina als context, onderaan het
// vraagveld (Ask me anything) en in de voet Contact. Het chatvenster zelf komt van bzz: /api/cw?w=chatjs&t=<taal> (zelfde domein curacao.day).
const CHAT = { nl: ['Vraag het in de chat', 'Een vraag over'], en: ['Ask in the chat', 'A question about'], de: ['Frag im Chat', 'Eine Frage zu'], es: ['Pregunta en el chat', 'Una pregunta sobre'], pt: ['Pergunte no chat', 'Uma pergunta sobre'] };
// Chat als hoofdknop op elke gids (Henkjan 13 nov 2026, advies "chat als hoofdknop op elke gids": de chat vraagt na het eerste antwoord om een
// mailadres, het gewone aanmeldblok leverde op de gidsen bijna niets op): een vraagveld met het onderwerp, dat het chatvenster van curacao.day opent
// met de vraag erin (window.cwPraat uit /api/cw?w=chatjs); zonder dat script gaat het naar #ama. Meting: gstat gids_chatvraag.
const CHATV = { nl: ['Vraag alles over', 'Vraag'], en: ['Ask anything about', 'Ask'], de: ['Frag alles über', 'Fragen'], es: ['Pregunta lo que quieras sobre', 'Preguntar'], pt: ['Pergunte o que quiser sobre', 'Perguntar'] };
function chatRegel(m, pag, titel) {
  const C = CHAT[m] || CHAT.en, V = CHATV[m] || CHATV.en, k = String(titel || '').replace(/<[^>]+>/g, '').replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim().slice(0, 90);
  let kort = k.split(/[:?]/)[0].trim(); if (/^g(?!bedrijf|hub)/.test(String(pag || '')) && m !== 'de' && /^[A-Z][a-zçé]/.test(kort)) kort = kort.charAt(0).toLowerCase() + kort.slice(1); // onderwerp klein ("trouwen op Curaçao"), namen van zaken niet
  const ond = 'gids.' + String(pag || 'gids').replace(/[^a-z0-9-]/g, '').slice(0, 40), ph = kort && kort.length < 60 ? V[0] + ' ' + kort + '…' : C[0] + '…';
  return '<form class="cwq" action="#ama" data-gond="' + esc(ond) + '" data-gondk="' + esc(k) + '" style="display:flex;gap:8px;margin:16px 0 8px;max-width:600px" onsubmit="var v=this.q.value.trim();try{fetch(\'/api/cw\',{method:\'POST\',headers:{\'content-type\':\'application/json\'},body:JSON.stringify({actie:\'gstat\',gr:\'gids_chatvraag\',taal:\'' + m + '\'}),keepalive:true})}catch(e){}if(window.cwPraat){window.cwPraat(this.getAttribute(\'data-gond\'),this.getAttribute(\'data-gondk\'),false,v);return false}">'
    + '<input name="q" enterkeyhint="send" placeholder="' + esc(ph) + '" style="flex:1;min-width:0;font:16px Inter,Arial,sans-serif;padding:13px 18px;border:1.5px solid #C9CFDB;border-radius:999px;color:var(--ink,#111113);background:var(--bg,#fff)">'
    + '<button type="submit" style="flex:none;border:0;border-radius:999px;background:#002B7F;color:#fff;font:800 15px Inter,Arial,sans-serif;padding:0 20px;cursor:pointer">' + esc(V[1]) + '</button></form>';
}
// de aanmelding ook bovenaan: na de kop en de eerste alinea, met daarboven de chatregel
export function metAanmeld(html, m, pag) {
  if (!THUIS) return html; const h = html.indexOf('</h1>'); if (h < 0) return html;
  const p = html.indexOf('</p>', h); const at = p > 0 && p - h < 1500 ? p + 4 : h + 5;
  const h1 = (html.match(/<h1[^>]*>([\s\S]*?)<\/h1>/) || [])[1] || '', regel = chatRegel(m, pag, h1);
  const mk = html.indexOf('<!--cwa-->'); if (mk > 0) return html.slice(0, mk) + regel + cwAanmeld(m, pag) + html.slice(mk + 10); // bedrijfspagina: eerst wat de zoeker wil (open nu, bellen, reviews), het aanmelden daarna (12 nov 2026)
  const al = html.indexOf('<section class="cwa"', at); if (al > 0 && al - at < 4000) return html.slice(0, at) + regel + html.slice(at); // er staat er al een vlak onder (plekpagina's: vraagBlok), niet twee keer hetzelfde vak (8 nov 2026)
  return html.slice(0, at) + regel + cwAanmeld(m, pag) + html.slice(at);
}
